  window.setSceneEnabled=value=>{sceneEnabled=!!value;for(const root of sceneRoots(document)){globalThis.NightScene?.dispose?.(root);root.hidden=!sceneEnabled;if(sceneEnabled)mountScenes(root);}return sceneEnabled;};
  window.setPuppetEnabled=value=>{dynamicPortraits=!!value;document.body.dataset.dynamicPortraits=String(dynamicPortraits);for(const root of document.querySelectorAll('.hero-portrait')){globalThis.NightPuppet?.dispose?.(root);if(dynamicPortraits)mountPuppets(root);}return dynamicPortraits;};
  window.setMotionMode(motionMode);
  document.body.dataset.dynamicPortraits='true';
  function setBusy(value){window.uiBusy=value;document.body.dataset.uiBusy=String(value);app.setAttribute('aria-busy',String(value));if(!value){idleWaiters.splice(0).forEach(resolve=>resolve());}}
  const stageNames={normal:'从容',wounded:'战痕',critical:'濒危'};
  function damageStage(hp,maxHp){return globalThis.NightPuppet?.stageFor?.(hp,maxHp)||(maxHp>0&&hp/maxHp<=.25?'critical':maxHp>0&&hp/maxHp<=.5?'wounded':'normal');}
  function heroId(){return game?.state.screen==='title'?chosenCharacter:(game?.state.character||game?.state.player?.character||(game?.state.starter==='sword'?'sword':'assassin'));}
  function hero(){return HEROES[heroId()]||HEROES.assassin;}
  function heroKind(){return hero().portrait||(heroId()==='sword'?'sword':'cat');}
  function heroQuote(cat,sword){return heroId()==='sword'?sword:cat;}
  function swordFallback(){return `<svg viewBox="0 0 500 760" aria-hidden="true"><defs><linearGradient id="sword-robes" x2="1" y2="1"><stop stop-color="#edf5f1"/><stop offset="1" stop-color="#476c8b"/></linearGradient></defs><path d="M166 200 Q92 220 86 516 L52 742 H429 L391 485 Q398 245 321 205Z" fill="#172938"/><path d="M169 214 L111 424 L79 754 H422 L373 425 L317 213Z" fill="url(#sword-robes)"/><path d="M196 237 L249 350 L301 239 L333 738 H173Z" fill="#b8d1db"/><path d="M171 335 Q254 372 331 335 L341 381 H158Z" fill="#284760"/><path d="M168 112 Q172 35 248 36 Q337 35 337 137 L319 278 L291 244 L297 144 L197 146 L196 270 L166 282Z" fill="#172330"/><ellipse cx="250" cy="157" rx="63" ry="84" fill="#eedbd2"/><path d="M186 128 Q200 43 273 65 L315 149 L281 109 L252 89 L214 142 L202 192 L184 214Z" fill="#182534"/><path d="M209 157 L236 159 M264 159 L291 155" stroke="#3a3542" stroke-width="4"/><path d="M214 161 L231 161 M269 160 L286 159" stroke="#9bddeb" stroke-width="3"/><path d="M240 205 Q252 200 264 204" fill="none" stroke="#985c6a" stroke-width="3"/><path d="M244 53 L267 20 L280 64" fill="#b3e9f7" stroke="#e7f6f9"/><path d="M366 271 L391 282 L337 662 L323 661Z" fill="#dfedee" stroke="#7cc3dc" stroke-width="3"/><path d="M350 319 L402 327 M376 283 L384 245" stroke="#aacbd3" stroke-width="8"/><g fill="#c2f4ff"><path d="M94 152 L103 174 L124 182 L103 190 L94 214 L87 190 L66 182 L87 174Z"/><path d="M373 98 L381 119 L398 126 L381 133 L373 155 L365 133 L348 126 L365 119Z"/></g></svg>`;}
  function heroSources(kind){return kind==='sword'?(assets.puppet?.sword||{}):(assets.puppet||{});}
  function portrait(kind,options={}){const player=['cat','sword'].includes(kind),p=game?.state.player||{hp:60,maxHp:60},stage=options.previewStage||damageStage(p.hp,p.maxHp),src=player?(heroSources(kind)[stage]||images[kind]):images[kind],hp=options.previewStage?({normal:60,wounded:30,critical:15})[stage]:p.hp,maxHp=options.previewStage?60:p.maxHp;return `<div class="portrait ${player?'hero-portrait '+kind+'-portrait damage-'+stage:''}" data-portrait="${kind}" ${player?`data-hp="${hp}" data-max-hp="${maxHp}" data-damage-stage="${stage}" ${options.previewStage?`data-preview-stage="${stage}"`:''}`:''}>${kind==='sword'?(YokaiArt.sword||swordFallback()):(YokaiArt[kind]||YokaiArt.paper)}${src&&!src.startsWith('__')?`<img src="${esc(src)}" alt="${esc(names[kind]||kind)}${player?' · '+stageNames[stage]:''}" onload="this.parentElement.classList.add('portrait-image-ready')" onerror="this.parentElement.classList.add('image-failed')">`:''}${player?`<span class="damage-stage-label" ${stage==='normal'?'hidden':''}>${stageNames[stage]}</span>`:''}</div>`;}
  function catRoots(scope){return [...(scope?.matches?.('.hero-portrait')?[scope]:[]),...(scope?.querySelectorAll?.('.hero-portrait')||[])];}
  function canPuppet(root){return root.dataset.portrait==='cat'||!!assets.puppetRig?.sword;}
  function puppetOptions(root){const sword=root.dataset.portrait==='sword';return {hp:Number(root.dataset.hp)||0,maxHp:Number(root.dataset.maxHp)||60,motion:motionMode,active:true,dynamic:dynamicPortraits,previewStage:root.dataset.previewStage||undefined,...(sword?{sources:assets.puppet?.sword,rig:assets.puppetRig?.sword}:{})};}
  function mountPuppets(scope){if(!dynamicPortraits)return;for(const root of catRoots(scope))if(canPuppet(root))globalThis.NightPuppet?.mount?.(root,puppetOptions(root));}
  function syncPuppets(scope){if(!dynamicPortraits)return;for(const root of catRoots(scope))if(canPuppet(root))globalThis.NightPuppet?.sync?.(root,puppetOptions(root));}
  function disposePuppets(scope){for(const root of catRoots(scope)){clearTimeout(root._reactionTimer);root.getAnimations?.().forEach(animation=>animation.cancel());globalThis.NightPuppet?.dispose?.(root);}}
  function syncPlayerAppearance(player){for(const root of app.querySelectorAll('[data-combatant="player"] .hero-portrait')){const previous=root.dataset.damageStage,stage=damageStage(player.hp,player.maxHp),kind=root.dataset.portrait,src=heroSources(kind)[stage]||images[kind];root.dataset.hp=String(player.hp);root.dataset.maxHp=String(player.maxHp);root.dataset.damageStage=stage;for(const id of ['normal','wounded','critical'])root.classList.toggle('damage-'+id,id===stage);const image=root.querySelector(':scope > img');if(image&&src&&image.getAttribute('src')!==src){root.classList.remove('image-failed','portrait-image-ready');image.src=src;}if(image)image.alt=names[kind]+' · '+stageNames[stage];const label=root.querySelector('.damage-stage-label');if(label){label.hidden=stage==='normal';label.textContent=stageNames[stage];}if(dynamicPortraits&&canPuppet(root))globalThis.NightPuppet?.sync?.(root,puppetOptions(root));if(previous&&previous!==stage){root.dataset.stageChanged=stage;const mark=fx('damage-transition','player',`<span>${stage==='normal'?'重新稳住气息':stage==='wounded'?'衣染战痕':'命火未熄'}</span>`);setTimeout(()=>{mark.remove();delete root.dataset.stageChanged;},motionMode==='fast'?150:750);}}}
  function puppetAct(type,options={}){const root=app.querySelector('[data-combatant="player"] .hero-portrait');if(!root)return;if(canPuppet(root))globalThis.NightPuppet?.act?.(root,type,{...options,motion:motionMode});sceneAct(type,options);root.dataset.reaction=type;clearTimeout(root._reactionTimer);root._reactionTimer=setTimeout(()=>{if(root.isConnected)delete root.dataset.reaction;},motionMode==='fast'?100:type==='revive'?700:430);}
  function sceneRoots(scope){return [...(scope?.matches?.('[data-scene]')?[scope]:[]),...(scope?.querySelectorAll?.('[data-scene]')||[])];}
  function sceneOptions(root){const s=game.state;return {mode:root.dataset.scene,map:s.map,availableNodes:s.availableNodes,history:s.history,currentNode:s.currentNode,character:heroId(),motion:motionMode,onNode:id=>{if(window.uiBusy||s.screen!=='map')return;selected=null;act(()=>game.enterNode(id));window.scrollTo(0,0);}};}
  function mountScenes(scope){for(const root of sceneRoots(scope)){root.hidden=!sceneEnabled;if(!sceneEnabled)continue;if(globalThis.NightScene)globalThis.NightScene.mount(root,sceneOptions(root));else root.dataset.sceneSupported='false';}}
  function syncScenes(scope){if(!sceneEnabled)return;for(const root of sceneRoots(scope))globalThis.NightScene?.sync?.(root,sceneOptions(root));}
  function disposeScenes(scope){for(const root of sceneRoots(scope))globalThis.NightScene?.dispose?.(root);}
  function sceneAct(type,options){for(const root of sceneRoots(app))if(root.dataset.scene==='battle')globalThis.NightScene?.act?.(root,type,options);}
  const relics=ids=>ids.map(id=>`<button class="relic ${treasureIds.includes(id)?'treasure':''}" data-action="relics" data-relic="${id}" title="${esc(RELICS[id]?.text)}"><i>${esc(relicGlyphs[id]||'宝')}</i>${esc(RELICS[id]?.name||id)}</button>`).join('');
  function artFallback(id,glyph){const n=Number(String(id).replace(/\D/g,''))||String(id).length,hue=(n*37+23)%360;return `<svg viewBox="0 0 400 240" aria-hidden="true"><defs><radialGradient id="art-${esc(id)}"><stop stop-color="hsl(${hue},32%,36%)"/><stop offset="1" stop-color="#112427"/></radialGradient></defs><rect width="400" height="240" fill="url(#art-${esc(id)})"/><g stroke="#d5ba7e" fill="none" opacity=".5"><circle cx="200" cy="120" r="${65+n%18}"/><path d="M${40+n%40} 200 Q200 ${-10-n%20} ${355-n%35} 200 M65 45 L335 195 M65 195 L335 45"/><ellipse cx="200" cy="120" rx="105" ry="${45+n%40}" transform="rotate(${n*13} 200 120)"/></g><text x="200" y="148" fill="#eed9b0" text-anchor="middle" font-family="serif" font-size="79">${esc(glyph||'契')}</text></svg>`;}
  function picture(kind,id,glyph,alt,cls=''){const src=assets[kind]?.[id];return `<div class="illustration ${cls}" ${kind==='cards'?`data-art-id="${esc(id)}"`:`data-event-art="${esc(id)}"`}>${artFallback(id,glyph)}${src?`<img src="${esc(src)}" alt="${esc(alt)}" loading="lazy" decoding="async" onerror="this.parentElement.classList.add('art-failed')">`:''}</div>`;}
  function encounterArt(id,name,glyph,whisper=''){return `<div class="encounter-frame">${picture('events',id,glyph,name,'encounter-art')}<div class="encounter-caption"><span>封域异闻 · ${esc(id.toUpperCase())}</span><b>${esc(name)}</b>${whisper?`<p>${esc(whisper)}</p>`:''}</div></div>`;}
  function relicCard(id,mode=''){const r=RELICS[id];if(!r)return '';const rare=treasureIds.includes(id),src=assets.relics?.[id];return `<${mode?'button':'article'} class="relic-card ${rare?'treasure':''}" ${mode?`data-action="choose-relic" data-relic="${id}"`:''}><span class="relic-rank">${rare?'天授秘宝':'封域珍藏'}</span><div class="relic-emblem"><span>${esc(relicGlyphs[id]||'宝')}</span>${src?`<img src="${esc(src)}" alt="${esc(r.name)}" onerror="this.style.display='none'">`:''}</div><h3>${esc(r.name)}</h3><p>${esc(r.text.replace(/^秘宝：/,''))}</p><small>${mode?'选择此宝 · 立刻生效':'已纳入本局行囊'}</small></${mode?'button':'article'}>`;}
  function hidePreview(){clearTimeout(previewTimer);document.getElementById('card-preview')?.remove();}
  function showPreview(el){if(!el||window.uiBusy||innerWidth<800||modal?.kind==='card-detail')return;const id=el.dataset.id;if(!CARDS[id])return;hidePreview();previewTimer=setTimeout(()=>{if(!el.isConnected)return;const box=document.createElement('aside');box.id='card-preview';box.className='card-preview';box.setAttribute('aria-hidden','true');box.innerHTML=cardMarkup(id,'detail');document.body.append(box);const r=el.getBoundingClientRect(),w=290,h=Math.min(490,innerHeight-35);box.style.width=w+'px';box.style.left=Math.max(12,Math.min(innerWidth-w-12,r.left+r.width/2-w/2))+'px';box.style.top=Math.max(12,Math.min(innerHeight-h-12,r.top-h-15))+'px';},260);}

  function toast(text){if(!text)return;clearTimeout(toastTimer);document.getElementById('toast-root').innerHTML=`<div class="toast">${esc(text)}</div>`;toastTimer=setTimeout(()=>document.getElementById('toast-root').innerHTML='',3000);}
  function cardCategory(c){return ({mark:'猎印',combo:'连段',blood:'血契',guard:'守势',basic:'基础',frost:'霜寒',sword:'剑意',ice:'霜寒',blade:'剑意'})[c.category]||c.category||c.archetype||(c.text.includes('标记')?'标记':c.text.includes('生命')?'血契':c.text.includes('本回合')||c.text.includes('连续')?'连段':c.attack?'攻击':'守势');}
  function rarity(c){return ({common:'常见',uncommon:'精巧',rare:'稀有',basic:'基础'})[c.rarity]||c.rarity||'常见';}
  function cardMarkup(card,mode=''){
    const id=typeof card==='string'?card:card.id,uid=typeof card==='string'?id:card.uid,c=CARDS[id];if(!c)return '';
    const bad=(mode==='hand'&&(window.uiBusy||game.state.battle.phase!=='player'||c.cost>game.state.battle.energy))||(mode==='reward'&&game.state.reward?.relicPending);
    const action=({hand:'card',reward:'reward',remove:'remove'})[mode],tag=action?'button':'article';
    return `<${tag} class="card ${c.attack?'attack':''} ${c.exhaust?'exhaust':''} ${selected===uid?'selected':''} rarity-${esc(c.rarity||'common')} ${mode==='detail'?'detail-card':''}" data-id="${id}" data-preview="true" ${!action?'tabindex="0"':''} ${action?`data-action="${action}" data-card="${esc(uid)}" ${bad?'disabled':''} aria-label="${esc(c.name)}，${c.cost} 灵力。${esc(c.text)}"`:''}><div class="card-top"><span class="cost">${c.cost}</span><h4>${esc(c.name)}</h4></div><div class="card-traits"><span>${esc(cardCategory(c))}</span><span>${esc(rarity(c))}</span><span class="card-class">${id.startsWith('S')?'剑修':'刺客'}</span></div>${picture('cards',id,c.sigil||(id.startsWith('S')?'剑':sigils[Number(id.slice(1))-1])||c.name[0],`${c.name}独立画卡`,'card-art')}<p>${esc(c.text)}</p><div class="card-foot"><span>${c.attack?'攻击':c.target?'咒术':'技法'}${c.exhaust?' · 消耗':''}</span><span>${mode==='reward'?(game.state.reward?.relicPending?'先选一件珍藏':'选择入组'):mode==='remove'?'移除此实例':mode==='hand'?(bad?(window.uiBusy?'结算中':c.cost>game.state.battle.energy?'灵力不足':'敌人回合'):c.target?(selected===uid?'再点取消':'点击后选敌'):'点击使用'):id}</span></div></${tag}>`;
  }
  function renderHud(){
    const s=game.state,p=s.player,b=s.battle,active=s.screen!=='title';
    document.getElementById('deck-nav').hidden=!active;document.getElementById('restart-nav').hidden=!active;
    hud.innerHTML=active?`<div class="hud"><div><div class="hud-label">生命 / 最大生命</div><div class="hud-value"><span id="hp-value">${p.hp}</span> <small>/ ${p.maxHp}</small></div><div class="hpbar"><i id="player-hp-bar" style="width:${100*p.hp/p.maxHp}%"></i></div></div>${s.screen==='battle'?`<div><div class="hud-label">当前灵力</div><div class="hud-value gold" id="energy-value">${b.energy}</div></div>`:''}<div><div class="hud-label">金币</div><div class="hud-value gold" id="gold-value">${p.gold}</div></div><div><div class="hud-label">寒渊封域 · ${esc(hero().profession)}</div><div class="hud-value">${cn[s.floor-1]||s.floor}<small> / ${s.map?.length||10} 区</small></div></div><div class="relic-row"><span class="hud-label">遗物</span>${relics(p.relics)}</div></div>`:'';
  }
  function starterCards(ids){const grouped={};for(const id of ids||[])grouped[id]=(grouped[id]||0)+1;return Object.entries(grouped).map(([id,count])=>`${CARDS[id]?.name||id}×${count}`).join(' · ');}
  function titleScreen(){const h=hero(),isSword=heroId()==='sword',ids=h.starters||[isSword?'sword':'mark'];const starters=Object.entries(STARTERS||{}).filter(([id])=>ids.includes(id));return `<section class="intro expedition-intro"><div class="intro-copy"><div class="eyebrow">THE SEALED ABYSS / 寒渊封域</div><h1>百妖夜契</h1><p class="subtitle">有些秘藏，不该被唤醒。</p><p class="story">玄烬教的引灵实验失控，整片寒渊在一夜间反噬。<br>黑雾遮断窥视，山川变形，活物难以久留。<br>正道奉命探查，魔教回收禁物，商盟与散修趁乱寻宝。<br>你也踏入此地——但并非为了同一个答案。</p><div class="character-options" role="group" aria-label="选择职业">${Object.entries(HEROES).map(([id,c])=>btn('character',`<span class="profession-mark">${id==='sword'?'剑':'影'}</span><span><b>${esc(c.name)}</b><small>${esc(c.profession)}</small><em>${id==='sword'?'清冷少言 · 剑意蓄发 · 霜寒制敌':'成年猫妖 · 猎印潜袭 · 连段收割'}</em></span>`,'character-option '+(heroId()===id?'chosen':''),`data-character="${id}" aria-pressed="${heroId()===id}"`)).join('')}</div><div class="hero-introduction"><span>${isSword?'太微剑宗 · 霜华剑修':'夜契盟 · 影契刺客'}</span><p>${isSword?'沈霜白只接了探查失踪弟子的命令。她不惯解释，也不喜争辩；长剑出鞘时，霜声便是答复。':'夜铃擅长从最薄弱处切入，以猎印追踪，以连击终结。寻找解契之法仍是她的私心，正如每个入域者都有未说出的打算。'}</p><b>“${isSword?'跟紧。别碰雾。':'宝物归谁，活着再谈。'}”</b></div><div class="starter-label">选择出发构筑 <span>独立职业牌池 · 10 张起手</span></div><div class="starter-options ${isSword?'single-starter':''}" role="group" aria-label="开局流派">${starters.map(([id,t])=>btn('starter',`<b>${esc(t.name)}</b><span>${esc(t.description)}</span><small>${esc(starterCards(t.cards))}</small>`,'starter-option '+(starter===id?'chosen':''),`data-starter="${id}" aria-pressed="${starter===id}"`)).join('')}</div><div class="actions">${btn('start','踏入封域　→','btn primary')}${btn('world','封域与势力','btn ghost')}${btn('catalogue',`查阅 ${Object.keys(CARDS).length} 张技能`,'btn ghost')}</div><p class="note">离线单人试玩 · 暂不保存进度，刷新将重新开始</p></div><div class="hero-showcase"><div class="intro-art">${portrait(heroKind())}<div class="nameplate">${esc(h.name)}<small>${esc(h.profession)} · ${isSword?'剑出霜生':'影落无声'}</small></div></div><section class="model-card"><div class="model-card-label"><span>行者身姿</span><small>移动鼠标可改变观察角度</small></div><div class="character-model" data-scene="character" role="img" aria-label="${esc(h.name)}的立体角色模型"><p class="scene-fallback">${isSword?'白袍、长剑与霜色剑光':'猫耳、尾巴与潜行双刃'} · 上方为角色原画</p></div></section></div></section>`;}
  function head(eyebrow,title,description,tag=''){return `<div class="screen-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2><p>${description}</p></div>${tag?`<span class="tag">${tag}</span>`:''}</div>`;}
  function mapScreen(){
    const s=game.state,map=s.map||[],available=new Set(s.availableNodes||[]),done=new Set(s.history.map(h=>h.id)),all=map.flat(),byId=Object.fromEntries(all.map(n=>[n.id,n]));
    const reachable=new Set(available),queue=[...available];while(queue.length){for(const next of byId[queue.shift()]?.next||[])if(!reachable.has(next)){reachable.add(next);queue.push(next);}}
    const width=140+(map.length-1)*136,pos=n=>{const row=map[n.floor-1]||[],count=row.length,y=count<=1?330:82+n.lane*(496/(count-1));return{x:70+(n.floor-1)*136,y};};
    const edges=all.flatMap(n=>(n.next||[]).map(next=>{const target=byId[next];if(!target)return '';const a=pos(n),b=pos(target),taken=done.has(n.id)&&done.has(next),current=n.id===s.currentNode&&available.has(next),future=reachable.has(n.id)&&reachable.has(next);return `<path class="map-edge ${taken?'taken':current?'available':future?'future':'blocked'}" data-from="${esc(n.id)}" data-to="${esc(next)}" d="M ${a.x+40} ${a.y} C ${a.x+71} ${a.y},${b.x-71} ${b.y},${b.x-40} ${b.y}"/>`;})).join('');
    const upcoming=all.filter(n=>available.has(n.id));
    return head('EXPEDITION / 寒渊封域','每条路，都有它的代价',`第${cn[s.floor-1]||s.floor}区：先看路线上的战斗、休息和奇遇，再选择进入。黑雾遮住的是事件真相，而非路线类型。`,`${s.history.length} / ${map.length} 区已探索`)+`<section class="expedition-model"><div class="scene-heading"><div><span class="eyebrow">寒渊残境</span><h3>封域沙盘</h3></div><p>亮起的地标可进入 · 路线选择后只能沿相连地标前进</p></div><div class="expedition-scene" data-scene="map" role="region" aria-label="寒渊封域立体沙盘"><p class="scene-fallback">立体场景不可用时，仍可通过下方路线选择继续探索。</p></div></section><div class="current-routes" aria-label="当前可选路线">${upcoming.map(n=>`<button class="route-choice type-${n.type}" data-action="node" data-node="${esc(n.id)}" data-type="${esc(n.type)}"><i>${nodes[n.type]?.[0]||'异'}</i><span><b>${esc(n.name||nodes[n.type]?.[1])}</b><small>${esc(n.description||nodes[n.type]?.[1])}</small></span><em>进入 →</em></button>`).join('')}</div><details class="route-details"><summary>展开完整路线 · 查看未来地标与连线</summary><div class="map-layout"><aside class="map-aside">${portrait(heroKind())}<p>“${heroQuote('选最值钱的路。也记得留下退路。','先看清路。再出剑。')}”</p><div class="map-key"><span><i class="key-current"></i>当前可选</span><span><i class="key-done"></i>已走过</span><span><i class="key-future"></i>未来可达</span><span><i class="key-blocked"></i>已错过的分支</span></div></aside><div class="map-scroll"><section class="tower-map route-map" style="width:${width}px;min-width:${width}px" aria-label="${map.length}区分支路线"><svg class="route-lines" viewBox="0 0 ${width} 648" aria-hidden="true">${edges}</svg>${map.map((floor,i)=>`<div class="route-floor" style="left:${70+i*136}px">第${cn[i]||i+1}区</div>`).join('')}${all.map(n=>{const p=pos(n),current=available.has(n.id),completed=done.has(n.id),blocked=!reachable.has(n.id)&&!completed,info=nodes[n.type]||nodes.event,title=`${n.name||info[1]}：${n.description||info[1]}${blocked?' · 此路已错过':completed?' · 已探索':''}`;return `<button class="map-node ${current?'current':completed?'completed':blocked?'passed':'future'} revealed" style="left:${p.x}px;top:${p.y}px" data-action="node" data-node="${esc(n.id)}" data-type="${esc(n.type)}" ${current?'':'disabled'} title="${esc(title)}" aria-label="${esc(title)}"><b>${info[0]}</b><span>${esc(n.name||info[1])}</span><small>${completed?'已探索':current?'可进入':blocked?'已错过':info[1]}</small></button>`;}).join('')}<div class="route-caption">不可横跳未连接分支 · 已探索区域不能返回刷取奖励</div></section></div></div></details><p class="note">路线每局生成，所有地标类型提前可见，奇遇内容进入时揭示。精英带来更强珍藏，也有更高风险；休息与商店同样会占用一次路线选择。</p>`;
  }
  function battleHint(b){if(heroId()==='sword'){if(b.enemy.chill)return `霜寒 ${b.enemy.chill}：敌人下次行动的每段攻击减少 ${b.enemy.chill}，行动后清除。意图已显示减伤后的准确数值。`;if((b.swordIntent||0)>=4)return `剑意 ${b.swordIntent}：可用强力剑诀消耗蓄积，斩出爆发。剑意跨回合保留，上限 8。`;return '施加霜寒压低连击，积累剑意后再出重剑。霜寒不冻结敌人，也不改变行动顺序。';}if(b.enemy.id==='snake'&&b.enemy.intentIndex===2&&b.enemy.mark)return '绛鳞即将蜕鳞清除猎印：考虑现在用扑杀兑现。';if(b.enemy.mark>=2)return `敌人已有 ${b.enemy.mark} 层猎印，扑杀基础伤害为 ${10+4*b.enemy.mark}。`;if(b.played===2&&game.state.player.relics.includes('jade'))return '再打一张牌，磨爪玉将返还 1 点灵力。';if(b.nextAttack)return `下一张攻击的第一段 +${b.nextAttack} 伤害，留给关键一击。`;return '影契刺客：猎印蓄杀 · 连段返利 · 血契换势，伺机切入敌人破绽。';}
  function battleScreen(){
    const s=game.state,b=s.battle,e=b.enemy,intent=game.getIntent?.()||ENEMIES[e.id].intents[e.intentIndex],active=b.phase==='player'&&!window.uiBusy,h=hero(),sword=heroId()==='sword';
    if(!active||!b.hand.some(c=>c.uid===selected))selected=null;
    return `<div class="battle-top"><span class="gold">第 ${b.turn} 回合 / ${active?'你的回合':'敌人行动中…'}</span><span class="muted">${selected?'点击敌人结算 · 再点同牌或 Esc 取消':'攻击／施加状态的牌先选牌再点敌人；其他牌点击即用'}</span></div><section class="battle-stage"><div class="battle-scenery" data-scene="battle" aria-hidden="true"></div><div class="stage-mist" aria-hidden="true"></div><div class="combatant player-combatant" data-combatant="player">${portrait(heroKind())}<div class="combatant-title"><h3>${esc(h.name)} <small class="muted">${esc(h.profession)}</small></h3><div class="stats"><span>护盾 <b class="gold" id="player-block">${b.block}</b></span><span ${!b.poison?'hidden':''}>毒 <b class="poison-color" id="player-poison">${b.poison}</b></span>${sword?`<span class="ice-stat" title="跨回合保留，上限8；仅指定剑诀会消耗">剑意 <b id="player-sword-intent" data-state="swordIntent">${b.swordIntent||0}</b> / 8</span>`:''}${b.nextAttack?`<span>蓄势 +${b.nextAttack}</span>`:''}${b.bloodPower?`<span>血力 +${b.bloodPower}</span>`:''}${b.riposte?`<span>反击 ${b.riposte}</span>`:''}</div></div></div><div class="intent"><small>下个敌方回合</small><h3>${esc(intent.name)}</h3><p id="intent-text">${esc(intent.text)}</p><div class="cycle">${e.id==='snake'?'鳞刃 → 蛇息 → 蜕鳞 → 绞缠':'按固定行动顺序循环'}</div><div class="combo-meter" id="combo-meter"><b>${b.played}</b><span>本回合出牌</span></div></div><div class="combatant enemy-combatant" data-combatant="enemy"><button class="enemy-target ${selected?'targetable':''}" data-action="target" ${!selected||!active?'disabled':''} aria-label="目标：${esc(e.name)}，生命 ${e.hp}，护盾 ${e.block}，猎印 ${e.mark}">${portrait(e.id)}<div class="combatant-title"><h3>${esc(e.name)}</h3><div class="stats"><span>生命 <b id="enemy-hp">${e.hp}</b> / ${e.maxHp}</span><span>护盾 <b class="gold" id="enemy-block">${e.block}</b></span><span ${sword&&!e.mark?'hidden':''}>猎印 <b class="gold" id="enemy-mark">${e.mark}</b> / 5</span>${sword||e.chill?`<span class="ice-stat" title="下次敌行动的每段攻击减少此数，行动后清空">霜寒 <b id="enemy-chill" data-state="chill">${e.chill||0}</b> / 4</span>`:''}${e.poison?`<span class="poison-color">毒 ${e.poison}</span>`:''}</div><div class="enemy-bar"><i id="enemy-hp-bar" style="width:${100*e.hp/e.maxHp}%"></i></div></div></button>${selected?`<div class="target-tip">点击敌人，${sword?'出剑':'发动潜袭'}</div>`:''}</div></section><div class="build-hint">${battleHint(b)}</div><div class="battle-tools"><div class="pile-buttons">${[['draw','抽牌堆'],['discard','弃牌堆'],['exhaust','消耗区']].map(([id,name])=>btn('pile',`${name}<b>${b[id].length}</b>`,'',`data-pile="${id}"`)).join('')}${btn('deck',`本局牌组<b>${s.player.deck.length}</b>`,'')}${btn('log','完整日志','')}</div>${btn('end-turn',active?'结束回合 →':'结算中…','btn primary',!active?'disabled':'')}</div><div class="hand-caption"><span>手牌 ${b.hand.length} / 10 · 本回合已打出 ${b.played} 张${b.nextEnergy||b.nextDraw?` · 下回合 +${b.nextEnergy||0} 灵力 / +${b.nextDraw||0} 抽牌`:''}</span><span>表现：${({full:'完整',fast:'快速',reduced:'减少动态'})[motionMode]} · 顶部「声画设置」可切换</span></div><section class="hand" aria-label="手牌">${b.hand.length?b.hand.map(c=>cardMarkup(c,'hand')).join(''):'<div class="empty">手牌已空，可以结束回合。</div>'}</section><div class="log-row"><span>战斗记录</span><div class="logs" id="recent-logs" aria-live="polite">${b.logs.slice(-8).map(log=>`<p>${esc(log)}</p>`).join('')}</div></div>`;
  }
  function rewardScreen(){
    const s=game.state,r=s.reward,fresh=!seenRewards.has(r)||(!r.relicPending&&!seenCardRewards.has(r));seenRewards.add(r);if(!r.relicPending)seenCardRewards.add(r);
    const strong=r.cards.some(id=>CARDS[id].rarity==='rare'),current=STARTERS[s.starter]?.name||'当前';
    return head('BATTLE WON / 夜契入手',r.relicPending?'珍藏现世，只取其一':strong?'金铃示宝，佳契在前':'战利入袖，再添一契',`每次战利至少一张${current}职业技能；精英战利必含一张稀有牌。先收好珍藏，再选择一张入组。`, `第${cn[s.floor-1]}层 · 战斗胜利`)+`<section class="loot-stage ${fresh?'loot-entrance':''} ${r.relicPending?'awaiting-relic':''}"><div class="loot-radiance" aria-hidden="true"></div><div class="reward-summary"><span class="coin-receipt"><i>钱</i>已入袋 <b>+${r.gold}</b> 金币</span>${r.relic?`<span class="relic-receipt">已收好：<b>${esc(RELICS[r.relic]?.name)}</b></span>`:''}<span class="muted">本局最高连招 ${s.stats.maxCombo||0} 张 · 最强一击 ${s.stats.maxHit||0}</span></div>${r.relicPending?`<div class="loot-section-label"><span>贰宝择壹</span><p>本次两件珍藏已固定，点击一件纳入行囊，效果立即生效。</p></div><div class="relic-choices">${(r.relicChoices||[]).map(id=>relicCard(id,'choose')).join('')}</div>`:r.relic?`<div class="collected-relic">${relicCard(r.relic)}<div><div class="eyebrow">已获得 · 效果生效</div><h3>它会陪你走完今夜</h3><p>${esc(RELICS[r.relic]?.text||'')}</p></div></div>`:''}<div class="loot-section-label card-choice-label"><span>${r.relicPending?'先纳珍藏，再揭技能':'择一张技能'}</span><p>${r.relicPending?'技能三选一仍在后方等候；领取珍藏后再从三张中取一张。':'暖金辉光标明稀有技能。悬停可查看放大的画面与完整规则。'}</p></div><div class="reward-cards">${r.cards.map((c,i)=>`<div class="reward-slot ${CARDS[c].rarity==='rare'?'rare-slot':''}" style="--reveal-delay:${i*95}ms"><i class="loot-beam" aria-hidden="true"></i>${cardMarkup(c,'reward')}${CARDS[c].category===s.starter?'<span class="synergy-tag">与你的起手流派呼应</span>':''}</div>`).join('')}</div><div class="reward-foot">${btn('reroll-reward',s.rewardRerolls>0&&!r.rerolled?'命运改签 · 免费重抽本屏三张':'本局改签已用尽','btn ghost',s.rewardRerolls>0&&!r.rerolled?'':'disabled')}${btn('skip-reward','跳过选牌，继续探索 →','btn ghost',r.relicPending?'disabled':'')}<small>改签本局仅一次，不改变金币与珍藏；每份战利只发放一次。</small></div></section>`;
  }
  function restScreen(){const p=game.state.player,amount=Math.min(18,p.maxHp-p.hp);return `<section class="event-layout">${encounterArt('rest','栖月温泉','息','且将金铃，暂寄雨声。')}<div class="event-copy"><div class="eyebrow">A MOMENT OF PEACE / 月下歇息</div><h2>且听，一夜雨声</h2><p class="story">隔绝黑雾的阵灯仍在燃烧。<br>${heroQuote('你将金铃拢入掌心，暂且不问来路。','你将长剑横置膝上，霜声渐息。')}</p><p class="description">当前生命 ${p.hp} / ${p.maxHp}。<br>休息恢复 18 点生命，不超过最大生命。此处只能停留一次。</p><div class="event-actions">${btn('rest',`静坐调息 · 恢复 ${amount} 点生命<small>治疗后沿当前路径继续</small>`,'btn primary','data-heal="true"')}${btn('rest','直接离开 →','btn ghost','data-heal="false"')}</div></div></section>`;}
  function foxScreen(){const p=game.state.player,ok=p.maxHp>8&&!p.relics.includes('fox');return `<section class="event-layout">${encounterArt('fox','狐影朱亭','契','八分命火，一线生机。')}<div class="event-copy"><div class="eyebrow">THE FOX'S BARGAIN / 狐灯邀约</div><h2>以寿，换一线生机</h2><p class="story">“别急着拒绝，${esc(hero().name)}。<br>我只收你八分命火——<br>换你命悬一线时，再睁一次眼。”</p><p class="description">签约后，最大生命 ${p.maxHp} → ${p.maxHp-8}；当前生命最高降至新上限。<br>获得「狐契」：本局下一次致命伤免死，生命设为 12（不超过最大生命）；触发后消失，后续伤害照常结算。</p><div class="event-actions">${btn('fox','签订狐契 · 最大生命 −8，获得一次免死<small>代价仅在本局生效，无隐藏惩罚</small>','btn primary',`data-sign="true" ${ok?'':'disabled'}`)}${!ok?'<p class="reason">最大生命不足，或已经持有狐契。</p>':''}${btn('fox','婉拒交易 · 数值不变，继续前进 →','btn ghost','data-sign="false"')}</div></div></section>`;}
  function eventScreen(){
    const e=game.state.event,faction=({riftwatch:'太微剑宗 · 封域观察哨',supply:'千灯商盟 · 流动补给',cultlab:'玄烬残众 · 实验遗址',swordgrave:'旧战场 · 无主剑冢',pilgrims:'散修 · 逐愿者',prisoner:'玄烬残众 · 被遗弃者',echo:'反噬回声 · 失序之地',broker:'千灯商盟 · 情报交易'})[e.id]||'封域旧闻 · 各有所求',story=(e.story||[e.description]).map(p=>`<p>${esc(p)}</p>`).join('');
    const art=encounterArt(e.id,e.name,e.glyph||'异',e.whisper||'');
    if(e.resolved)return `<section class="event-layout">${art}<div class="event-copy"><div class="eyebrow">AFTER THE CHOICE / 异闻结局</div><h2>${esc(e.name)}</h2><div class="event-faction">${esc(faction)}</div><div class="event-story">${story}</div><div class="event-outcome"><span>你做出的选择</span><b>${esc(e.choiceLabel||'')}</b><p>${esc(e.outcome||'')}</p><small>${esc(e.received||'没有取走任何东西')}</small></div>${eventLootPreview(e)}<div class="event-actions">${btn('event-leave','带着所得继续探索 →','btn primary')}</div></div></section>`;
    return `<section class="event-layout">${art}<div class="event-copy"><div class="eyebrow">${esc(e.kicker||'A STRANGE ENCOUNTER / 封域异闻')}</div><h2>${esc(e.name)}</h2><div class="event-faction">${esc(faction)}</div><div class="event-story">${story}</div><p class="description">${esc(e.description)}<br>选择后不会立刻离开；先看这段异闻的结局，再决定往哪里走。</p><div class="event-actions">${e.choices.map((c,i)=>btn('event-choice',`${esc(c.label)}<small>${esc(c.text||'')}</small>`,'btn '+(i===0?'primary':'ghost'),`data-index="${i}" ${c.disabled?'disabled':''}`)).join('')}</div>${e.choices.some(c=>c.disabled)?'<p class="reason">灰掉的选项表示当前生命、金币或牌组不够支付代价。</p>':''}</div></section>`;
  }
  function eventLootPreview(e){const chosen=e.choices?.find(c=>c.label===e.choiceLabel),held=game.state.player.relics;return `<div class="event-loot-preview">${chosen?.relic&&held.includes(chosen.relic)&&e.received?.includes(`秘宝「${RELICS[chosen.relic]?.name}」`)?relicCard(chosen.relic):''}${(chosen?.cardIds||[]).map(id=>cardMarkup(id)).join('')}</div>`;}
  function shopScreen(){const s=game.state,p=s.player,shop=s.shop;return head('THE NIGHT MARKET / 无名夜市','钱货两清，不问来处','非基础牌每张 35 金币，每件商品每次到访仅能购买一次。',`可用金币 ${p.gold}`)+`<div class="shop-layout">${encounterArt('shop','夜市珍阁','市','金铃作响，钱货两清。')}<aside class="shop-note"><h3>断契 · 删牌</h3><p>永久移除本局牌组中的一个指定实例。<br>牌组最少保留 5 张。</p><p>每次到访仅一次，价格 40 金币。</p>${btn('remove-panel',shop.removed?'本次删牌已使用':'40 金币 · 选择要移除的牌','btn ghost',shop.removed||p.gold<40||p.deck.length<=5?'disabled':'')}<div class="reason">${shop.removed?'已完成本次服务':p.deck.length<=5?'牌组已达 5 张下限':p.gold<40?'金币不足 40':'选中具体实例后才扣款'}</div></aside><div class="shop-goods">${shop.cards.map((c,i)=>`<div class="shop-item">${cardMarkup(c.id)}${btn('buy',c.bought?'已售出':'35 金币 · 购买',`btn ${!c.bought&&p.gold>=35?'primary':'ghost'}`,`data-index="${i}" ${c.bought||p.gold<35?'disabled':''}`)}<div class="reason">${c.bought?'已加入本局牌组':p.gold<35?'金币不足 35':'下场战斗洗入牌堆'}</div></div>`).join('')}</div></div><div class="shop-bottom"><span>商品进入时固定，查看牌组不会刷新。</span>${btn('leave-shop','离开商店 →','btn primary')}</div>`;}
  function endingScreen(win){const s=game.state,p=s.player;return `<section class="ending"><div class="ending-copy"><div class="eyebrow">${win?'THE ABYSS REMAINS / 封域初探完结':'THE FOG REMEMBERS / 探查未归'}</div><h2>${win?'雾未散，人已归':'此行，未能归'}</h2><p class="story">${win?`绛鳞倒下，实验核心的裂隙暂时沉寂。<br>你带回一枚残缺的实验铭牌，各方已经等在雾外。<br>“${heroQuote('价钱，得重新谈。','人未找全。我会再来。')}”<br>寒渊的真相，仍有一半藏在黑雾里。`:`你倒在第${cn[(s.result?.floor||s.floor)-1]||s.floor}区，败于${esc(s.result?.enemy||'封域异物')}。<br>黑雾再次合拢，留下无人认领的脚印。<br>下一次，换一条路，或换一种出牌的方式。`}</p><div class="ending-stats"><span>生命 <b>${p.hp}</b> / ${p.maxHp}</span><span>金币 <b>${p.gold}</b></span><span>牌组 <b>${p.deck.length}</b> 张</span><span>战胜 <b>${s.stats.battles}</b> 场</span><span>最高连招 <b>${s.stats.maxCombo||0}</b></span><span>最强一击 <b>${s.stats.maxHit||0}</b></span></div><div class="ending-relics">${relics(p.relics)}</div><div class="ending-route">本次路线：${s.history.map(h=>esc(h.name||nodes[h.type]?.[1]||h.type)).join(' → ')}</div><div class="actions">${btn('start','再入寒渊封域 · 相同职业','btn primary')}${btn('title','返回首页，切换职业','btn ghost')}${btn('deck','查看最终牌组','btn ghost')}</div><p class="note">重新开始将清空本局生命变化、金币、牌组增删、遗物与路线进度。</p></div>${portrait(heroKind())}</section>`;}
  function render(){if(!game||holdRender)return;if(game.state.screen!=='title'){starter=game.state.starter;chosenCharacter=game.state.character||chosenCharacter;}hidePreview();disposePuppets(app);disposeScenes(app);renderAudioToggle();renderHud();const previous=lastScreen;lastScreen=game.state.screen;document.body.dataset.screen=lastScreen;document.body.dataset.character=heroId();const pages={title:titleScreen,map:mapScreen,battle:battleScreen,reward:rewardScreen,rest:restScreen,fox:foxScreen,event:eventScreen,shop:shopScreen,victory:()=>endingScreen(true),defeat:()=>endingScreen(false)};app.innerHTML=(pages[game.state.screen]||titleScreen)();mountPuppets(app);mountScenes(app);if(modal)renderModal();const logs=document.getElementById('recent-logs');if(logs)logs.scrollTop=logs.scrollHeight;if(previous!==lastScreen)screenCue(lastScreen);}
  function renderAudioToggle(){const state=audio()?.getState?.()||{muted:false,volume:.3},el=document.getElementById('audio-nav');if(el){el.textContent=state.muted?'声音：关':'声音：开';el.setAttribute('aria-pressed',String(state.muted));}}
  function screenCue(screen){if(screen==='reward')audio()?.playCue?.(game.state.reward?.cards.some(id=>CARDS[id].rarity==='rare')?'rareReveal':'rewardReveal');if(['fox','rest','shop','event'].includes(screen)){const id=screen==='event'?game.state.event.id:screen;lastEncounter=id;audio()?.playEncounter?.(id);}if(screen==='victory')audio()?.playCue?.('win');if(screen==='defeat')audio()?.playCue?.('death');}
  function openModal(kind,pile){if(window.uiBusy)return;selected=null;modal={kind,pile};render();modalRoot.querySelector('button')?.focus();}
  function closeModal(){disposePuppets(modalRoot);disposeScenes(modalRoot);modal=null;modalRoot.innerHTML='';render();}
  function rules(){return `<div class="rules"><section><h3>灵力与回合</h3><p>玩家先手。每回合先清空旧护盾，结算毒，再恢复基础 3 灵力、抽 5 张牌。手牌上限 10，溢出进入弃牌堆。</p><p>攻击／施加状态的牌先点卡牌，再点敌人；再次点同牌或 Esc 取消，不扣灵力。无目标牌点击即用。动作结算期间暂不能重复出牌。</p><p>结束回合弃掉剩余手牌并清除临时蓄势，敌人执行展示的固定行动。敌人旧护盾在其自己回合开始时清空。</p></section><section><h3>影契刺客 · 夜铃</h3><p>「猎印」即卡牌上的标记，最多 5 层，跨回合保留；窥隙铺垫，扑杀兑现。只有写明互动的牌受到标记影响。</p><p>「连段」用低费、抽牌和返还灵力延长出牌。候机只增强下一张攻击的第一段，连爪每爪独立结算。</p><p>「血契」以生命换抽牌、伤害或持续成长；自损无视护盾，生命不足会死亡。夜铃可选三套起手，后续奖励来自刺客牌池。</p></section><section><h3>霜华剑修 · 沈霜白</h3><p>「剑意」上限 8，跨回合保留。剑诀按各自说明蓄积或消耗剑意；没有写消耗的剑招不会自动扣层。</p><p>「霜寒」上限 4，令敌人下次行动的每一段攻击减少对应数值，最低为 0。敌人完整行动结束后清除，即使本次行动没有攻击也会清除；不会冻结、跳过或打乱意图。</p><p>霜寒减伤已计入界面显示的敌人意图。剑修有独立起始牌组、霜印遗物和技能奖励／商店池，与刺客构筑分开。</p></section><section><h3>伤害、牌堆与秘宝</h3><p>普通伤害先扣护盾再扣生命；自损和毒无视护盾。毒在持有者回合开始造成当前层数的直接生命伤害，随后减 1。</p><p>消耗牌本场不再抽回，下场恢复。商店删除指定实例，本局永久移除。抽牌堆空时重洗弃牌，正在结算的牌不会抽回自己。</p><p>遗物与秘宝的完整效果可点击顶栏查看。精英珍藏先二选一，再选卡；同一份战利只会发放一次。休息恢复 18，狐契以 8 最大生命换一次免死。</p></section><section><h3>封域路线与异闻</h3><p>本幕十个区域，多列地标由真实连线连接。战斗、精英、休息、商店和奇遇类型提前可见，只有相连的亮起地标可进入。选路后无法返回，也不能跳到未连接的分支。</p><p>地图与立体沙盘使用同一份状态；关闭立体场景或设备不支持时，仍可用路线卡和完整路线图游玩。</p><p>十四种剧情异闻每局尽量不重复：先读前情，再看代价与所得，选择后查看结局，再继续探索。全程离线，无存档；刷新会重新开始。</p></section></div>`;}
  function worldLore(){return `<div class="world-lore"><p class="world-prologue">寒渊原是群山之间的采灵之地。玄烬教试图从地底引出一段不属于此世的灵性，却在最后一夜被仪式反噬。黑雾封住整片区域，山路和建筑渐渐失去原本的形状。外界的占卜、传讯与窥视均告失效，只能让活人走进去。</p><div class="faction-grid"><article><i>剑</i><h3>太微剑宗</h3><p>受托探查并寻找失踪弟子。有人只想救人，也有人想替正道先封存禁术。</p></article><article><i>烬</i><h3>玄烬残众</h3><p>回收实验记录与失控造物；想补救的人和想继续实验的人同行，却互不信任。</p></article><article><i>灯</i><h3>千灯商盟</h3><p>以补给换取遗物、记忆与情报。危险会抬高价钱，也会催生别人的机会。</p></article><article><i>影</i><h3>夜契盟与散修</h3><p>受雇寻物，或为自身执念而来。身上的契约、未偿的债与想带走的东西各不相同。</p></article></div><p class="note">雾外无人看清寒渊全貌。同行者未必同心，偶遇者也未必无害；你能带回多少真相，取决于你愿意走进哪些地方。</p></div>`;}
  function renderModal(){
    const s=game.state;let title='',hint='',body='';
    if(modal.kind==='rules'){title='玩法手札';hint='看清意图、选择路径，再决定何时出手。';body=rules();}
    if(modal.kind==='world'){title='寒渊封域 · 各怀所求';hint='禁术反噬之后，没有一方愿意空手离开。';body=worldLore();}
    if(modal.kind==='catalogue'){const entries=Object.keys(CARDS).filter(id=>catalogueFilter==='all'||(catalogueFilter==='sword'?id.startsWith('S'):!id.startsWith('S')));title=`技能图鉴 · ${entries.length} 种`;hint='两职业使用独立的奖励与商店池；这里可查看所有技能的费用和完整效果。';body=`<div class="catalogue-filters">${[['all','全部技能'],['assassin','影契刺客'],['sword','霜华剑修']].map(([id,name])=>btn('catalogue-filter',name,'btn small '+(catalogueFilter===id?'primary':'ghost'),`data-filter="${id}"`)).join('')}</div><div class="deck-grid catalogue">${entries.map(id=>cardMarkup(id)).join('')}</div>`;}
    if(modal.kind==='settings'){title='声画与战斗表现';hint='这些设置只改变表现，不改变规则或奖励。';body=`<div class="settings-options">${[['full','完整表现','刺客潜袭、剑修剑芒、逐段命中与受击姿态。'],['fast','快速表现','更短的动作与数字停留，适合重复试玩。'],['reduced','减少动态','取消位移、晃动和闪烁，保留数值与战损换装。']].map(([mode,name,text])=>btn('motion',`<b>${name}${motionMode===mode?' · 已选择':''}</b><small>${text}</small>`,'btn '+(motionMode===mode?'primary':'ghost'),`data-mode="${mode}"`)).join('')}</div><section class="portrait-settings"><h3>${esc(hero().name)} · 角色表现</h3><p>生命降至 50% 与 25% 时，衣装和神态显示不同战痕；恢复生命后回到对应状态。人物模型与路线场景可独立关闭，保留原画与完整路线操作。夜铃另有动态立绘，剑修以原画和人物模型呈现。</p><div class="actions">${btn('scene-toggle',sceneEnabled?'立体场景：开':'立体场景：关','btn ghost',`aria-pressed="${sceneEnabled}"`)}${btn('puppet-toggle',dynamicPortraits?'夜铃动态立绘：开':'夜铃动态立绘：关','btn ghost',`aria-pressed="${dynamicPortraits}"`)}${btn('portrait-gallery','展开三态画卷','btn ghost')}</div></section>${soundSettings()}`;}
    if(modal.kind==='portrait-gallery'){const sword=heroId()==='sword';title=hero().name+' · 三态画卷';hint='这里只预览立绘，不改变生命、战斗或本局进度。血量以当前最大生命的比例计算。';body=`<div class="damage-gallery">${[['normal',sword?'静心':'从容','生命高于 50%',sword?'白袍齐整，目光清寒。':'衣袍齐整，金瞳含笑。'],['wounded','战痕','生命不高于 50%',sword?'衣角染尘，剑锋仍稳。':'外袍磨损，神色警觉。'],['critical','濒危','生命不高于 25%',sword?'霜衣破损，握剑不退。':'衣袖破损，疲惫而不退。']].map(([stage,name,threshold,text])=>`<article class="damage-gallery-card" data-stage="${stage}">${portrait(heroKind(),{previewStage:stage})}<div><span>${threshold}</span><h3>${name}</h3><p>${text}</p></div></article>`).join('')}</div><div class="actions">${btn('settings','返回声画设置','btn ghost')}</div>`;}
    if(modal.kind==='relics'){title='今夜的珍藏';hint='每件效果都已在本局生效；战斗中触发时会显示名称。';body=`<div class="relic-gallery">${s.player.relics.map(id=>relicCard(id)).join('')}</div>`;}
    if(['deck','remove'].includes(modal.kind)){const remove=modal.kind==='remove';title=remove?'选择一张牌，断去此契':'本局牌组';hint=remove?`40 金币，仅移除点击的一个实例。目前 ${s.player.deck.length} 张，至少保留 5 张。`:`共 ${s.player.deck.length} 张，起手流派「${STARTERS?.[s.starter]?.name||'标记'}」。每张是独立实例，战斗消耗不改变牌组。`;body=`<div class="deck-grid">${s.player.deck.slice().sort((a,b)=>a.id.localeCompare(b.id)).map(c=>cardMarkup(c,remove?'remove':'')).join('')}</div>`;}
    if(modal.kind==='pile'){const labels={draw:'抽牌堆',discard:'弃牌堆',exhaust:'本场消耗区'},cards=s.battle[modal.pile];title=`${labels[modal.pile]} · ${cards.length} 张`;hint=modal.pile==='draw'?'按卡号展示，实际抽取顺序隐藏；查看不会改变顺序。':modal.pile==='exhaust'?'本场不再抽回，下一场恢复。':'抽牌堆空时将这些牌洗回。';body=cards.length?`<div class="deck-grid">${cards.slice().sort((a,b)=>a.id.localeCompare(b.id)).map(c=>cardMarkup(c)).join('')}</div>`:'<p class="muted">这里暂时没有卡牌。</p>';}
    if(modal.kind==='log'){title='本场战斗记录';hint='按发生顺序展示，保留最近 90 条。';body=s.battle.logs.map(l=>`<p style="line-height:2">${esc(l)}</p>`).join('');}
    if(modal.kind==='restart'){title='重新开始这一夜？';body=`<p class="muted">当前进度将清空。保留当前起手流派重新开始，或返回首页切换流派。</p><div class="actions">${btn('start','重新开始','btn primary')}${btn('title','返回首页选流派','btn ghost')}${btn('close','继续当前游戏','btn ghost')}</div>`;}
    disposePuppets(modalRoot);modalRoot.innerHTML=`<div class="overlay" data-overlay="true"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-head"><div><h2>${title}</h2><p>${hint}</p></div>${btn('close','×','close','aria-label="关闭面板"')}</div>${body}</section></div>`;mountPuppets(modalRoot);
  }
  function soundSettings(){const state=audio()?.getState?.()||{volume:.3,muted:false};return `<section class="sound-settings"><h3>剑鸣与妖术之声</h3><p>刺客的爪击、火符与血契，剑修的剑鸣、碎冰与霜寒，按实际结算逐段发声。</p><div class="sound-controls">${btn('audio-toggle',state.muted?'开启声音':'静音','btn ghost',`aria-pressed="${state.muted}"`)}<label for="audio-volume">总音量 <b id="volume-value">${Math.round((state.volume??.3)*100)}%</b></label><input id="audio-volume" data-action="volume" type="range" min="0" max="100" value="${Math.round((state.volume??.3)*100)}" aria-label="总音量"></div><div class="audio-previews">${(heroId()==='sword'?[['S01','霜锋'],['S05','寒芒'],['S12','霜天壁'],['S16','万川归寂']]:[['C01','爪击'],['C15','妖火符'],['C16','残月'],['C02','敛息'],['C13','血契'],['C24','狂爪']]).map(([id,name])=>btn('audio-preview','试听 · '+name,'btn ghost small',`data-id="${id}"`)).join('')}</div><p class="note">浏览器首次点击后启用声音。静音设置仅作用于当前打开的页面。</p></section>`;}
  function acquisition(id,rect,relic=false){hidePreview();audio()?.playCue?.(relic?(treasureIds.includes(id)?'treasure':'relic'):(CARDS[id]?.rarity==='rare'?'rareReveal':'rewardReveal'));if(!relic)audio()?.playCard?.(id);const el=document.createElement('div');el.className='acquisition '+(relic?'acquisition-relic':'');el.dataset.fx='acquire';el.innerHTML=relic?relicCard(id):cardMarkup(id,'detail');el.style.left=(rect?.left??innerWidth/2-110)+'px';el.style.top=(rect?.top??innerHeight*.3)+'px';fxRoot.append(el);if(motionMode==='full'){const target=document.querySelector(relic?'.relic-row':'#deck-nav')?.getBoundingClientRect();el.animate([{opacity:0,transform:'scale(.8)'},{opacity:1,transform:'scale(1.08)',offset:.3},{opacity:1,transform:'scale(1)',offset:.6},{opacity:0,transform:`translate(${(target?.left??innerWidth-100)-(rect?.left??innerWidth/2-110)}px,${(target?.top??40)-(rect?.top??innerHeight*.3)}px) scale(.12)`}],{duration:920,easing:'cubic-bezier(.2,.7,.3,1)',fill:'forwards'});}setTimeout(()=>el.remove(),motionMode==='full'?960:350);toast(`${relic?'珍藏入袖':'新招入组'} · ${relic?RELICS[id]?.name:CARDS[id]?.name}`);}
  function act(fn){const ok=fn();if(game.state.notice)toast(game.state.notice);return ok!==false;}
  const delay=ms=>new Promise(resolve=>setTimeout(resolve,motionMode==='fast'?Math.min(25,ms*.08):motionMode==='reduced'?Math.min(230,ms):ms));
  function center(target){const el=document.querySelector(`[data-combatant="${target}"] .portrait`),r=el?.getBoundingClientRect();return r?{x:r.left+r.width/2,y:r.top+r.height*.43,w:r.width,h:r.height}:{x:innerWidth/2,y:innerHeight*.35,w:200,h:250};}
  function fx(type,target,markup,extra=''){const p=center(target),el=document.createElement('div');el.className=`fx fx-${type} ${extra}`;el.dataset.fx=type;el.style.left=p.x+'px';el.style.top=p.y+'px';el.innerHTML=markup;fxRoot.append(el);return el;}
  function numberFX(target,value,label='',kind='damage'){return fx('number',target,`<b>${esc(value)}</b><small>${esc(label)}</small>`,kind);}
  function actorGhost(actor,enemy){if(motionMode!=='full'||!actor)return null;const image=actor.querySelector(':scope > img'),rect=actor.getBoundingClientRect();if(!image?.src)return null;const el=document.createElement('div');el.className='fx-actor-ghost '+(enemy?'enemy-ghost':'');el.dataset.fx='afterimage';el.style.cssText=`left:${rect.left}px;top:${rect.top}px;width:${rect.width}px;height:${rect.height}px`;el.innerHTML=`<img src="${esc(image.src)}" alt="">`;fxRoot.append(el);el.animate([{opacity:.5,transform:'translateX(0) scale(1)'},{opacity:.2,transform:`translateX(${enemy?35:-35}px) scale(.97)`,offset:.45},{opacity:0,transform:`translateX(${enemy?55:-55}px) scale(.94)`}],{duration:340,easing:'ease-out',fill:'forwards'});return el;}
  function attackMotion(actor,enemy,heavy){if(!actor||motionMode!=='full')return;const sword=!enemy&&heroId()==='sword',distance=Math.min(sword?(heavy?76:55):(heavy?130:105),innerWidth*.085),sign=enemy?-1:1;actor.animate([{transform:'translateX(0) rotate(0) scale(1)'},{transform:`translateX(${-sign*9}px) translateY(3px) rotate(${-sign*2}deg) scale(.98)`,offset:.16},{transform:`translateX(${sign*distance}px) translateY(-9px) rotate(${sign*2}deg) scale(1.08)`,offset:.39},{transform:`translateX(${sign*distance}px) translateY(-9px) rotate(${sign*2}deg) scale(1.08)`,offset:.48},{transform:'translateX(0) rotate(0) scale(1)'}],{duration:heavy?500:430,easing:'cubic-bezier(.18,.8,.26,1)'});}
